import React from 'react';
import {ThemeProvider, type Theme} from '@gravity-ui/uikit';

const STORAGE_KEY = 'app-theme';

export interface ThemeState {
  theme: Theme;
  setTheme: (theme: Theme) => void;
}

export const ThemeStateContext = React.createContext<ThemeState | undefined>(undefined);

function getInitialTheme(): Theme {
  if (typeof window === 'undefined') return 'system';
  const saved = window.localStorage.getItem(STORAGE_KEY);
  return saved === 'light' || saved === 'dark' || saved === 'system' ? saved : 'system';
}

export function ThemeStateProvider({children}: React.PropsWithChildren) {
  const [theme, setThemeState] = React.useState<Theme>(getInitialTheme);

  const setTheme = React.useCallback((next: Theme) => {
    setThemeState(next);
    window.localStorage.setItem(STORAGE_KEY, next);
  }, []);

  const value = React.useMemo(() => ({theme, setTheme}), [theme, setTheme]);

  return (
    <ThemeStateContext.Provider value={value}>
      <ThemeProvider theme={theme}>{children}</ThemeProvider>
    </ThemeStateContext.Provider>
  );
}

export function useThemeState(): ThemeState {
  const ctx = React.useContext(ThemeStateContext);
  if (!ctx) throw new Error('useThemeState must be used within ThemeStateProvider');
  return ctx;
}
